def read_counts(path):
    rows = {}
    with open(path, "r", encoding="utf-8") as handle:
        reader = csv.reader(handle, delimiter="\t")
        header = next(reader)
        if header[:4] != ["GeneID", "Counts_unstrand", "Counts_firstStrand", "Counts_secondStrand"]:
            raise ValueError("unexpected STAR GeneCounts header: " + repr(header))
        for fields in reader:
            if not fields or fields[0].startswith("N_"):
                continue
            rows[fields[0]] = tuple(int(x) for x in fields[1:4])
    return rows


